import React from 'react';
import CodeBlock from '@theme/CodeBlock';
// @ts-ignore — generated by `npm run build:plugin-jsdocs` (from docs/site) from
// webapp/channels/src/plugins/registry.ts; gitignored build output, see docs/site/.gitignore.
import rawDocs from '@site/data/plugin-jsdocs.json';
import styles from './styles.module.css';

type JsMethodDocs = {
  Name: string;
  Parameters: string[];
  Comments: string[];
};

type JsDocs = {
  Interface: {
    Methods: JsMethodDocs[];
  };
};

const docs: JsDocs | undefined = rawDocs?.Interface?.Methods?.length > 0 ? (rawDocs as JsDocs) : undefined;

function signature(method: JsMethodDocs): string {
  return `${method.Name}(${method.Parameters.join(', ')})`;
}

/**
 * Renders the web app plugin registry method reference, generated from the JSDoc comments above
 * each `PluginRegistry` method/property in `webapp/channels/src/plugins/registry.ts` by
 * `gen-plugin-jsdocs`. Port of the old mattermost-developer-documentation Hugo `pluginjsdocs`
 * shortcode.
 */
export default function PluginJsDocs() {
  if (!docs) {
    return (
      <p>
        Run <code>npm run build:plugin-jsdocs</code> (from <code>docs/site</code>) to generate this
        documentation.
      </p>
    );
  }

  const methods = docs.Interface.Methods;

  return (
    <div className={styles.pluginJsDocs}>
      <ul className={styles.toc}>
        {methods.map((m) => (
          <li key={m.Name}>
            <a href={`#${m.Name}`}>{signature(m)}</a>
          </li>
        ))}
      </ul>
      <hr />
      {methods.map((m) => (
        <div key={m.Name} className={styles.method}>
          <h3 id={m.Name}>{m.Name}</h3>
          <CodeBlock language="js">{`/**\n${m.Comments.map((c) => ` * ${c}`).join('\n')}\n */\n${signature(m)}`}</CodeBlock>
        </div>
      ))}
    </div>
  );
}
